6: /* ───────────────────────── AUDIO ───────────────────────── */
7: const Sfx = (() => {
8:   let ctx = null;
9:   let muted = localStorage.getItem('hydroharvest_muted') === '1';
10:   function unlock() {
11:     if (!ctx) { try { ctx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { ctx = null; } }
12:     if (ctx && ctx.state === 'suspended') ctx.resume();
13:   }
14:   function tone(freq, dur, opts) {
15:     opts = opts || {};
16:     if (muted) return;
17:     unlock(); if (!ctx) return;
18:     const type = opts.type || 'sine', vol = opts.vol || 0.05, delay = opts.delay || 0;
19:     const t0 = ctx.currentTime + delay;
20:     const osc = ctx.createOscillator(), gain = ctx.createGain();
21:     osc.type = type;
22:     osc.frequency.setValueAtTime(freq, t0);
23:     if (opts.slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, opts.slide), t0 + dur);
24:     gain.gain.setValueAtTime(0.0001, t0);
25:     gain.gain.exponentialRampToValueAtTime(vol, t0 + 0.014);
26:     gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
27:     osc.connect(gain).connect(ctx.destination);
28:     osc.start(t0); osc.stop(t0 + dur + 0.03);
29:   }
30:   function play(name) {
31:     switch (name) {
32:       case 'click': tone(760, 0.05, { type: 'triangle', vol: 0.025 }); break;
33:       case 'plant': tone(392, 0.1, { vol: 0.05 }); tone(523, 0.12, { delay: 0.07, vol: 0.05 }); break;
34:       case 'harvest': [523, 659, 784].forEach((f, i) => tone(f, 0.16, { delay: i * 0.08, vol: 0.05 })); break;
35:       case 'sell': tone(880, 0.08, { type: 'triangle', vol: 0.04 }); tone(1174, 0.14, { delay: 0.07, type: 'triangle', vol: 0.04 }); break;
36:       case 'buy': tone(330, 0.09, { vol: 0.045 }); tone(440, 0.12, { delay: 0.08, vol: 0.045 }); break;
37:       case 'place': tone(190, 0.1, { vol: 0.05, slide: 120 }); tone(320, 0.08, { delay: 0.05, vol: 0.04 }); break;
38:       case 'error': tone(150, 0.16, { type: 'sawtooth', vol: 0.035, slide: 90 }); break;
39:       case 'day': tone(392, 0.2, { vol: 0.02 }); tone(587, 0.24, { delay: 0.1, vol: 0.018 }); break;
40:       case 'fanfare': [523, 659, 784, 1046].forEach((f, i) => tone(f, 0.22, { delay: i * 0.1, vol: 0.045 })); break;
41:       case 'goal': [659, 784, 988, 1318].forEach((f, i) => tone(f, 0.18, { delay: i * 0.07, type: 'triangle', vol: 0.045 })); break;
42:       default: break;
43:     }
44:   }
45:   function setMuted(v) {
46:     muted = v;
47:     localStorage.setItem('hydroharvest_muted', v ? '1' : '0');
48:     updateMuteButtons();
49:   }
50:   return { play, unlock, setMuted, toggle: () => setMuted(!muted), isMuted: () => muted };
51: })();
