398: /* ───────────────────────── SIMULATION ───────────────────────── */
399: function simulate(dt) {
400:   if (!state || !state.speed) return;
401:   const scaled = dt * state.speed;
402:   state.dayTime += scaled / DAY_LENGTH;
403:   if (state.dayTime >= 1) {
404:     state.dayTime -= 1;
405:     advanceDay();
406:     if (!state) return;
407:   }
408:   const frac = scaled / DAY_LENGTH;
409:   for (const bed of state.beds) simulateBed(bed, frac);
410:   if (Date.now() - lastSaveAt > 20000) saveGame(true);
411: }
412: 
413: function simulateBed(bed, frac) {
414:   if (!bed.cropId) return;
415:   const crop = cropById(bed.cropId);
416:   const sys = BED_TYPES[bed.type].spec;
417:   const plants = BED_TYPES[bed.type].plants;
418:   const auto = state.upgrades.autoDoser && bed.type !== 'kratky';
419: 
420:   if (auto) {
421:     bed.water = maxWater();
422:     bed.ph += (6.0 - bed.ph) * Math.min(1, frac * 14);
423:     const mid = (crop.ec[0] + crop.ec[1]) / 2;
424:     bed.ec += (mid - bed.ec) * Math.min(1, frac * 14);
425:   } else if (bed.water > 0.05) {
426:     bed.water = Math.max(0, bed.water - frac * plants * 0.95 * sys.water * (state.upgrades.reservoir ? 0.72 : 1));
427:     bed.ec = Math.max(0.2, bed.ec - frac * 0.24);
428:     bed.ph = Math.min(8.2, bed.ph + frac * 0.10);
429:   }
430: 
431:   const scores = bedScores(bed, crop);
432:   const condMin = bed.water <= 0.05 ? 0 : Math.min(scores.ph, scores.ec, scores.temp);
433:   const ledBonus = state.upgrades.led ? 1.3 : 1;
434:   bed.growth = Math.min(1, bed.growth + (frac / crop.growDays) * condMin * sys.growth * ledBonus);
435: 
436:   const stress = 1 - Math.min(scores.ph, scores.ec, scores.temp);
437:   const waterStress = bed.water <= 0.05 ? 1 : 0;
438:   const worst = Math.max(stress, waterStress);
439:   const healthDelta = worst > 0.3 ? -8 * frac : 4 * frac;
440:   bed.health = clamp(bed.health + healthDelta, 0, 100);
441: 
