452:   const prevWeather = state.weather;
453:   state.weather = rollWeather();
454:   updateMarket();
455:   chargeUpkeep();
456:   if (!state) return;
457:   expireContracts();
458:   if (state.contracts.offers.length < 3 && Math.random() < 0.8) offerContract();
459:   checkGoals();
460:   snapshotCash();
461:   if (state.cash < 0 && !state.godMode) toast(`⚠️ Estás ${fmtMoney(-state.cash)} en rojo. Vendé producción o recortá costos.`, 'bad');
462:   const w = WEATHERS[state.weather];
463:   logEvent('weather', `Día ${state.day}: ${w.label} · ${greenhouseTemp()} °C en invernadero · caja ${state.godMode ? '∞' : fmtMoney(state.cash)}.`);
464:   if (prevWeather !== state.weather) logEvent('weather', `Cambio de clima: ${WEATHERS[prevWeather].label} → ${w.label}.`);
465:   if (state.day % 7 === 0) {
466:     const week = Math.floor((state.day - 1) / 7) + 1;
467:     logEvent('system', `Cierre de semana ${week}: ${state.beds.length} camas, ${state.beds.filter(b => b.cropId).length} en producción, caja ${state.godMode ? '∞' : fmtMoney(state.cash)}.`);
468:   }
469:   if (state.weather === 'heatwave') toast(`🥵 ¡Ola de calor! Invernadero a ${greenhouseTemp()}°C — ${state.upgrades.hvac ? 'el HVAC está peleando.' : 'los cultivos sufren estrés térmico. Considerá HVAC o media sombra.'}`, 'warn');
470:   else if (state.weather === 'storm') toast('⛈️ Tormenta afuera. El colector de lluvia está trabajando a pleno.', 'warn');
471:   else if (state.weather === 'rain') toast('🌧️ Día de lluvia: agua gratis y raíces contentas.');
472:   Sfx.play('day');
473:   updateHUD(true);
474:   if (openModalId === 'modal-market') renderMarket();
475:   if (openModalId === 'modal-contracts') renderContracts();
476:   if (openModalId === 'modal-dashboard') renderDashboard();
477:   saveGame(true);
478:   if (state.cash < -750 && !state.godMode) triggerGameOver();
