481: function rollWeather() {
482:   const total = WEATHER_WEIGHTS.reduce((a, [, w]) => a + w, 0);
483:   let r = Math.random() * total;
484:   for (const [key, weight] of WEATHER_WEIGHTS) { r -= weight; if (r <= 0) return key; }
485:   return 'sunny';
486: }
487: function updateMarket() {
488:   let spike = null;
489:   for (const crop of CROPS) {
490:     const m = state.market[crop.id];
491:     m.prev = m.price;
492:     const drift = (crop.basePrice - m.price) * 0.28 + (Math.random() - 0.5) * crop.basePrice * 0.24;
493:     m.price = clamp(m.price + drift, crop.basePrice * 0.55, crop.basePrice * 1.65);
494:     if (Math.random() < 0.045) {
495:       m.price = clamp(m.price * 1.35, crop.basePrice * 0.55, crop.basePrice * 1.95);
496:       spike = crop;
497:     }
498:   }
499:   if (spike) toast(`📈 ¡Pico de demanda! ${spike.name} está caro hoy.`);
500: }
501: function chargeUpkeep() {
502:   if (state.godMode) return;
503:   const beds = state.beds.length;
504:   const energy = state.beds.reduce((sum, b) => sum + BED_TYPES[b.type].spec.energy, 0);
505:   const autoBeds = state.beds.filter(b => b.type !== 'kratky').length;
506:   const cost = Math.max(1, Math.round(2 + energy + state.upgrades.hvac * 3 + (state.upgrades.led ? 6 : 0) + (state.upgrades.autoDoser ? autoBeds * 1.2 : 0) + (state.upgrades.rain ? 0.5 : 1.5)));
507:   changeCash(-cost);
508:   if (beds) {
509:     state.beds.forEach(b => {
510:       const rec = state.stats.bySystem[b.type];
511:       if (rec) rec.upkeep += cost / beds;
512:     });
513:   }
514:   const low = state.beds.filter(b => b.cropId && b.water < 8);
515:   if (low.length) toast(`💧 ${low.length} cama${low.length > 1 ? 's' : ''} con poca solución nutritiva.`, 'warn');
516: }
