689: function placementValid(type, x, z) {
690:   if (state && state.godMode) return true;
691:   const h = bedHalf(type);
692:   if (x - h.w < -11.7 || x + h.w > 11.7) return false;
693:   if (z - h.d < -5.2 || z + h.d > 5.2) return false;
694:   for (const b of state.beds) {
695:     const bh = bedHalf(b.type);
696:     if (Math.abs(x - b.x) < h.w + bh.w + 0.22 && Math.abs(z - b.z) < h.d + bh.d + 0.22) return false;
697:   }
698:   return true;
699: }
