141:     g.lineTo(0, r); g.quadraticCurveTo(0, 0, r, 0); g.closePath();
142:     g.fill(); g.stroke();
143:     g.textAlign = 'center'; g.textBaseline = 'middle';
144:     lines.forEach((line, i) => {
145:       g.fillStyle = i === 0 ? (opts.titleColor || '#eafff2') : (opts.color || '#b9d8c8');
146:       g.font = `${i === 0 ? '800' : '600'} ${i === 0 ? fs : Math.round(fs * 0.72)}px "Segoe UI", Arial, sans-serif`;
147:       g.fillText(line, W / 2, pad + lh * i + lh / 2 + (i === 0 ? 1 : 2));
148:     });
149:     const tex = new THREE.CanvasTexture(c);
150:     tex.encoding = THREE.sRGBEncoding;
151:     tex.minFilter = THREE.LinearFilter;
152:     const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false, depthWrite: false });
153:     const sp = new THREE.Sprite(mat);
154:     const scale = opts.scale || 0.006;
155:     sp.scale.set(W * scale, H * scale, 1);
156:     sp.renderOrder = 20;
157:     return sp;
158:   }
