250:   function buildGreenhouse() {
251:     const { w, d, wallH, ridgeH } = GREENHOUSE;
252:     const glass = new THREE.MeshLambertMaterial({ color: 0xd8f2ff, transparent: true, opacity: 0.16, side: THREE.DoubleSide, depthWrite: false });
253:     const frameMat = new THREE.MeshStandardMaterial({ color: 0xd3cfc2, roughness: 0.62, metalness: 0.3 });
254:     const W = w / 2, D = d / 2;
255: 
256:     // walls (4 planes)
257:     const mkWall = (ww, hh) => new THREE.Mesh(new THREE.PlaneGeometry(ww, hh), glass);
258:     const south = mkWall(w, wallH); south.position.set(0, wallH / 2, D); scene.add(south);
259:     const north = mkWall(w, wallH); north.position.set(0, wallH / 2, -D); north.rotation.y = Math.PI; scene.add(north);
260:     const east = mkWall(d, wallH); east.position.set(W, wallH / 2, 0); east.rotation.y = -Math.PI / 2; scene.add(east);
261:     const west = mkWall(d, wallH); west.position.set(-W, wallH / 2, 0); west.rotation.y = Math.PI / 2; scene.add(west);
262: 
263:     // gable triangles (east & west ends)
264:     const tri = new THREE.Shape();
265:     tri.moveTo(-D, wallH); tri.lineTo(D, wallH); tri.lineTo(0, ridgeH); tri.closePath();
266:     const triGeo = new THREE.ShapeGeometry(tri);
267:     const endE = new THREE.Mesh(triGeo, glass); endE.rotation.y = -Math.PI / 2; endE.position.x = W; scene.add(endE);
268:     const endW = new THREE.Mesh(triGeo, glass); endW.rotation.y = Math.PI / 2; endW.position.x = -W; scene.add(endW);
269: 
270:     // roof planes
271:     const slopeLen = Math.hypot(D, ridgeH - wallH);
272:     const roofGeo = new THREE.PlaneGeometry(w, slopeLen);
273:     const roofAngle = Math.atan2(ridgeH - wallH, D);
274:     const roofS = new THREE.Mesh(roofGeo, glass);
275:     roofS.position.set(0, (wallH + ridgeH) / 2, D / 2); roofS.rotation.x = roofAngle - Math.PI / 2; scene.add(roofS);
276:     const roofN = new THREE.Mesh(roofGeo, glass);
277:     roofN.position.set(0, (wallH + ridgeH) / 2, -D / 2); roofN.rotation.x = Math.PI / 2 - roofAngle; scene.add(roofN);
278: 
279:     // ── frame beams ──
280:     const beam = (bw, bh, bd, x, y, z, rz) => {
281:       const b = new THREE.Mesh(new THREE.BoxGeometry(bw, bh, bd), frameMat);
282:       b.position.set(x, y, z); if (rz) b.rotation.z = rz; b.castShadow = true; scene.add(b); return b;
283:     };
284:     const col = (x, z) => beam(0.22, wallH, 0.22, x, wallH / 2, z);
285:     // corner + intermediary columns
286:     [-W, -W / 2, 0, W / 2, W].forEach(x => { col(x, D); col(x, -D); });
287:     [-D, 0, D].forEach(z => { col(W, z); col(-W, z); });
288:     // wall-top plates
289:     beam(w, 0.24, 0.24, 0, wallH, D); beam(w, 0.24, 0.24, 0, wallH, -D);
290:     beam(0.24, 0.24, d, W, wallH, 0); beam(0.24, 0.24, d, -W, wallH, 0);
291:     // ridge beam
292:     beam(w + 0.4, 0.28, 0.28, 0, ridgeH, 0);
293:     // roof sloped beams (every 4 m)
294:     const slopeBeamLen = slopeLen + 0.3;
295:     [-W, -W / 2, 0, W / 2, W].forEach(x => {
296:       const b1 = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.18, slopeBeamLen), frameMat);
297:       b1.position.set(x, (wallH + ridgeH) / 2, D / 2); b1.rotation.x = roofAngle; b1.castShadow = true; scene.add(b1);
298:       const b2 = b1.clone(); b2.position.set(x, (wallH + ridgeH) / 2, -D / 2); b2.rotation.x = -roofAngle; scene.add(b2);
299:     });
300:     // gable end struts
301:     [W, -W].forEach(x => { beam(0.18, ridgeH - wallH + 0.2, 0.18, x, (ridgeH + wallH) / 2, 0); });
302: 
303:     // door (south, center)
304:     const door = new THREE.Mesh(new THREE.BoxGeometry(2.4, 2.5, 0.14), new THREE.MeshStandardMaterial({ color: 0x2c3a33, roughness: 0.6, metalness: 0.3 }));
305:     door.position.set(0, 1.25, D + 0.02); scene.add(door);
306:   }
