429:   function plantMound(crop, growth, rng) {
430:     const g = new THREE.Group();
431:     const s = 0.42 + growth * 1.05;
432:     const bumps = growth > 0.55 ? 5 : 4;
433:     for (let i = 0; i < bumps; i++) {
434:       const r = (0.19 + rng() * 0.09) * s;
435:       const m = new THREE.Mesh(new THREE.IcosahedronGeometry(r, 0), leafMat(crop.leaf));
436:       const a = (i / bumps) * Math.PI * 2 + rng();
437:       m.position.set(Math.cos(a) * 0.16 * s, r * 0.75, Math.sin(a) * 0.16 * s);
438:       m.castShadow = true; g.add(m);
439:     }
440:     // crown sprout above
441:     const crown = new THREE.Mesh(new THREE.ConeGeometry(0.11 * s, 0.3 * s, 6), leafMat(crop.leaf));
442:     crown.position.y = 0.24 * s; g.add(crown);
443:     g.scale.setScalar(0.62 + growth * 0.95);
444:     return g;
445:   }
