447:   function fruitingPlant(crop, growth, rng) {
448:     const g = new THREE.Group();
449:     const stemH = 0.55 + growth * 1.15;
450:     const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.036, stemH, 6), leafMat(0x4b7a3a));
451:     stem.position.y = stemH / 2; stem.castShadow = true; g.add(stem);
452:     // leaf clusters
453:     const clusters = 2 + Math.floor(growth * 3);
454:     for (let i = 0; i < clusters; i++) {
455:       const y = 0.35 + (i / clusters) * (stemH - 0.3);
456:       const leaf = new THREE.Mesh(new THREE.IcosahedronGeometry(0.13 + rng() * 0.06, 0), leafMat(crop.leaf));
457:       leaf.position.set((rng() - 0.5) * 0.24, y, (rng() - 0.5) * 0.24);
458:       leaf.scale.y = 0.7; g.add(leaf);
459:     }
460:     const fruits = [];
461:     if (crop.fruit && growth > 0.68) {
462:       const n = 2 + Math.floor((growth - 0.68) * 9);
463:       for (let i = 0; i < Math.min(5, n); i++) {
464:         const f = new THREE.Mesh(new THREE.SphereGeometry(0.075 + rng() * 0.02, 8, 6),
465:           new THREE.MeshLambertMaterial({ color: crop.fruit, emissive: crop.fruit, emissiveIntensity: 0.25 }));
466:         f.position.set((rng() - 0.5) * 0.4, 0.35 + rng() * (stemH - 0.35), (rng() - 0.5) * 0.4);
467:         f.castShadow = true; g.add(f); fruits.push(f);
468:       }
469:     }
470:     g.scale.setScalar(0.68 + growth * 0.8);
471:     return { group: g, fruits };
472:   }
