722:   let lastPipeSig = '';
723:   function setBedVisuals(beds, day) {
724:     const seen = new Set();
725:     for (const bed of beds) {
726:       seen.add(bed.id);
727:       const existing = bedMeshes.get(bed.id);
728:       const signature = JSON.stringify([bed.type, bed.cropId, Math.round((bed.growth || 0) * 24), Math.round(bed.health || 100), day || 0]);
729:       if (existing && existing.signature === signature) continue;
730:       if (existing) { bedsGroup.remove(existing.group); disposeObject(existing.group); }
731:       const built = buildBedMesh(bed, day);
