734:       bedsGroup.add(built.group);
735:       bedMeshes.set(bed.id, { ...built, signature });
736:     }
737:     for (const [id, rec] of bedMeshes) {
738:       if (!seen.has(id)) { bedsGroup.remove(rec.group); disposeObject(rec.group); bedMeshes.delete(id); }
