744:   function samplePath(pts, t) {
745:     const segs = [];
746:     let total = 0;
747:     for (let i = 0; i < pts.length - 1; i++) {
748:       const len = pts[i].distanceTo(pts[i + 1]);
749:       segs.push({ a: pts[i], b: pts[i + 1], len });
750:       total += len;
751:     }
752:     let d = t * total;
753:     for (const sg of segs) {
754:       if (d <= sg.len) return sg.a.clone().lerp(sg.b, d / sg.len);
755:       d -= sg.len;
756:     }
757:     return pts[pts.length - 1].clone();
758:   }
