760:   function rebuildPipes(beds) {
761:     if (!pipeGroup) return;
762:     const sig = beds.map(b => `${b.id}:${b.type}:${b.x}:${b.z}`).join('|');
763:     if (sig === lastPipeSig) return;
764:     lastPipeSig = sig;
765:     while (pipeGroup.children.length) {
766:       const c = pipeGroup.children.pop();
767:       if (c.geometry) c.geometry.dispose();
768:       if (c.material) c.material.dispose();
769:     }
770:     pipes = []; flowDots = [];
771:     const source = new THREE.Vector3(-9.4, 0.11, -6.0);
772:     const supplyMat = new THREE.LineBasicMaterial({ color: 0x38d6e0, transparent: true, opacity: 0.8, depthWrite: false });
773:     const returnMat = new THREE.LineBasicMaterial({ color: 0xffc44d, transparent: true, opacity: 0.7, depthWrite: false });
774:     const dotGeo = new THREE.SphereGeometry(0.075, 8, 6);
775:     const dotSup = new THREE.MeshBasicMaterial({ color: 0x8bf4ff });
776:     const dotRet = new THREE.MeshBasicMaterial({ color: 0xffd98a });
777: 
778:     const addLine = (pts, mat) => {
779:       const geo = new THREE.BufferGeometry().setFromPoints(pts);
780:       const line = new THREE.Line(geo, mat);
781:       pipeGroup.add(line);
782:       pipes.push(line);
783:     };
784: 
785:     beds.forEach((b, i) => {
786:       const h = bedHalf(b.type);
787:       const supplyPts = [
788:         source.clone(),
789:         new THREE.Vector3(b.x, 0.11, source.z),
790:         new THREE.Vector3(b.x, 0.11, b.z - h.d - 0.12),
791:       ];
792:       const returnPts = [
793:         new THREE.Vector3(b.x + 0.2, 0.115, b.z - h.d - 0.12),
794:         new THREE.Vector3(b.x + 0.2, 0.115, source.z + 0.3),
795:         new THREE.Vector3(source.x + 0.55, 0.115, source.z + 0.3),
796:       ];
797:       addLine(supplyPts, supplyMat);
798:       addLine(returnPts, returnMat);
799: 
800:       const sup = new THREE.Mesh(dotGeo, dotSup); pipeGroup.add(sup);
801:       flowDots.push({ mesh: sup, pts: supplyPts, t: (i * 0.17) % 1, speed: 0.15 + (i % 3) * 0.03 });
802:       const ret = new THREE.Mesh(dotGeo, dotRet); pipeGroup.add(ret);
803:       flowDots.push({ mesh: ret, pts: returnPts, t: (0.5 + i * 0.11) % 1, speed: 0.12 + (i % 2) * 0.03 });
804:     });
805: 
806:     const t1 = textSprite(['IDA', 'agua + nutrientes'], { scale: 0.0045, fontSize: 20, border: '#38d6e0' });
807:     t1.position.set(source.x + 0.4, 0.55, source.z - 0.3); pipeGroup.add(t1);
808:     const t2 = textSprite(['VUELTA', 'drenaje al tanque'], { scale: 0.0045, fontSize: 20, border: '#ffc44d', titleColor:'#ffe6ad' });
809:     t2.position.set(source.x + 1.25, 0.3, source.z + 0.7); pipeGroup.add(t2);
810: 
811:     pipeGroup.visible = blueprintOn;
812:   }
